/**
 * Internal identity generation.
 *
 * IDs are opaque and generated by us — callers never supply them. Directory-safe by
 * construction (lowercase hex, fixed length), which is what lets the filesystem layout
 * use them as path components without sanitisation (ADR-0003).
 */
import { randomUUID } from 'node:crypto';
/** 32-char lowercase hex, no dashes. Safe as a single path segment on every platform. */
export function newId() {
    return randomUUID().replaceAll('-', '');
}
const ID_RE = /^[0-9a-f]{32}$/;
export function isId(value) {
    return typeof value === 'string' && ID_RE.test(value);
}
